/// FTL. Cost 0. Deal 5/6 damage; if fewer than PlayMax(3/4) cards have
/// finished playing this turn, draw 1. Bead `sts2-rs-kii5y` corrects the
/// Python-pin port which inverted the gate (`>= 2` → only fired on plays
/// 3+, opposite of C# `num < PlayMax` which fires on plays 1-3) and
/// dropped the upgraded PlayMax bump. C# `Ftl.cs` CanDrawCard checks
/// CardPlaysFinished_this_turn_by_owner < PlayMax.IntValue; FTL itself is
/// not yet finished during OnPlay, so the threshold uses the pre-FTL
/// count. Upgrade bumps Damage +1 (via base spec) AND PlayMax +1.
pub(crate) fn play_ftl(state: &mut CombatState, target: Option<CreatureUid>) -> EffectResult {
    let t = target.expect("Ftl: Enemy-targeted");
    let base = current_card_damage(state);
    let _ = deal_damage_player_to_enemy(state, t, base);
    let play_max = if current_card_upgraded(state) { 4 } else { 3 };
    if state.count_player_cards_played_this_turn(None) < play_max {
        let _ = sts2_core::cards::draw_via_state(state, 1);
    }
    EffectResult::Resolved
}

